const menu=document.querySelector('.mobile-menu'),mobileNav=document.querySelector('#mobile-nav');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Abrir menú':'Cerrar menú');mobileNav.hidden=open;});
mobileNav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobileNav.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menú');}));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&mobileNav&&!mobileNav.hidden){mobileNav.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menú');menu.focus();}});
const filters=[...document.querySelectorAll('[data-filter]')],stories=[...document.querySelectorAll('.stories .story')],more=document.querySelector('#more-stories'),grid=document.querySelector('.stories');let expanded=false,current='Todas las historias';
function filterStories(){let visible=0;stories.forEach((story,i)=>{const show=current==='Todas las historias'?(expanded||i<3):story.dataset.category===current;story.hidden=!show;if(show)visible++;});if(grid)grid.classList.toggle('filtered',current!=='Todas las historias');if(more)more.hidden=current!=='Todas las historias'||expanded;const status=document.querySelector('#filter-status');if(status)status.textContent=`${visible} historias en ${current.toLowerCase()}`;}
filters.forEach(button=>button.addEventListener('click',()=>{current=button.dataset.filter;filters.forEach(b=>{const selected=b===button;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected));});filterStories();}));
more?.addEventListener('click',()=>{expanded=true;filterStories();const link=stories[3]?.querySelector('a');link?.focus({preventScroll:true});stories[3]?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});});
const save=document.querySelector('.save-story');if(save){const key='santuario-saved-'+save.dataset.slug;function update(saved){save.setAttribute('aria-pressed',String(saved));save.innerHTML=saved?'<span aria-hidden="true">♥</span> Lectura guardada':'<span aria-hidden="true">♡</span> Guardar lectura';}try{update(localStorage.getItem(key)==='1');}catch{}save.addEventListener('click',()=>{const saved=save.getAttribute('aria-pressed')!=='true';try{localStorage.setItem(key,saved?'1':'0');update(saved);}catch{save.textContent='No se pudo guardar en este navegador';}});}
